    /// Seed constructor format strings for UE5 math/color/margin types.
    /// Key is (type_name, arg_count) so we can support multiple overloads.
    fn seed_constructor_formats(&mut self) {
        // FVector constructors
        self.constructor_formats
            .insert(("FVector".into(), 0), "FVector::ZeroVector".into());
        self.constructor_formats
            .insert(("FVector".into(), 1), "FVector({0})".into());
        self.constructor_formats
            .insert(("FVector".into(), 3), "FVector({0}, {1}, {2})".into());

        // FVector2D constructors
        self.constructor_formats
            .insert(("FVector2D".into(), 0), "FVector2D::ZeroVector".into());
        self.constructor_formats
            .insert(("FVector2D".into(), 1), "FVector2D({0})".into());
        self.constructor_formats
            .insert(("FVector2D".into(), 2), "FVector2D({0}, {1})".into());

        // FVector4 constructors
        self.constructor_formats.insert(
            ("FVector4".into(), 4),
            "FVector4({0}, {1}, {2}, {3})".into(),
        );

        // FRotator constructors
        self.constructor_formats
            .insert(("FRotator".into(), 0), "FRotator::ZeroRotator".into());
        self.constructor_formats
            .insert(("FRotator".into(), 3), "FRotator({0}, {1}, {2})".into());

        // FQuat constructors
        self.constructor_formats
            .insert(("FQuat".into(), 0), "FQuat::Identity".into());
        self.constructor_formats
            .insert(("FQuat".into(), 4), "FQuat({0}, {1}, {2}, {3})".into());

        // FTransform constructors
        self.constructor_formats
            .insert(("FTransform".into(), 0), "FTransform::Identity".into());

        // FLinearColor constructors
        self.constructor_formats.insert(
            ("FLinearColor".into(), 0),
            "FLinearColor::Transparent".into(),
        );
        self.constructor_formats.insert(
            ("FLinearColor".into(), 3),
            "FLinearColor({0}f, {1}f, {2}f, 1.0f)".into(),
        );
        self.constructor_formats.insert(
            ("FLinearColor".into(), 4),
            "FLinearColor({0}f, {1}f, {2}f, {3}f)".into(),
        );

        // FColor constructors (sRGB 0-255)
        self.constructor_formats
            .insert(("FColor".into(), 3), "FColor({0}, {1}, {2}, 255)".into());
        self.constructor_formats
            .insert(("FColor".into(), 4), "FColor({0}, {1}, {2}, {3})".into());

        // FMargin constructors (Slate padding)
        self.constructor_formats
            .insert(("FMargin".into(), 0), "FMargin(0.0f)".into());
        self.constructor_formats
            .insert(("FMargin".into(), 1), "FMargin({0}f)".into());
        self.constructor_formats
            .insert(("FMargin".into(), 2), "FMargin({0}f, {1}f)".into());
        self.constructor_formats.insert(
            ("FMargin".into(), 4),
            "FMargin({0}f, {1}f, {2}f, {3}f)".into(),
        );

        // Property string formats for ImportText/ExportText
        self.property_string_formats
            .insert("FVector".into(), "(X={0},Y={1},Z={2})".into());
        self.property_string_formats
            .insert("FVector2D".into(), "(X={0},Y={1})".into());
        self.property_string_formats
            .insert("FRotator".into(), "(Pitch={0},Yaw={1},Roll={2})".into());
        self.property_string_formats
            .insert("FLinearColor".into(), "(R={0},G={1},B={2},A={3})".into());
        self.property_string_formats
            .insert("FColor".into(), "(R={0},G={1},B={2},A={3})".into());
        self.property_string_formats.insert(
            "FTransform".into(),
            "(Rotation=(X=0,Y=0,Z=0,W=1),Translation=(X={0},Y={1},Z={2}),Scale3D=(X=1,Y=1,Z=1))"
                .into(),
        );
    }
