#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_builtin_aliases() {
        let kb = EngineKnowledge::new();
        assert_eq!(kb.resolve_type_alias("Vec3"), Some("FVector"));
        assert_eq!(kb.resolve_type_alias("Actor"), Some("AActor"));
        assert_eq!(
            kb.resolve_type_alias("NiagaraSystem"),
            Some("UNiagaraSystem")
        );
        assert_eq!(kb.resolve_type_alias("NonExistent"), None);
    }

    #[test]
    fn test_builtin_includes() {
        let kb = EngineKnowledge::new();
        assert_eq!(kb.get_include("AActor"), Some("GameFramework/Actor.h"));
        assert_eq!(
            kb.get_include("UStaticMeshComponent"),
            Some("Components/StaticMeshComponent.h")
        );
        // Test unprefixed lookup
        assert_eq!(kb.get_include("Actor"), Some("GameFramework/Actor.h"));
        assert_eq!(
            kb.get_include("StaticMeshComponent"),
            Some("Components/StaticMeshComponent.h")
        );
    }

    #[test]
    fn test_legacy_compat() {
        let kb = EngineKnowledge::new();
        let result = kb.resolve_call("println", &["FString(TEXT(\"hello\"))".to_string()]);
        assert!(result.is_some());
        assert!(result.unwrap().contains("UE_LOG"));
    }

    #[test]
    fn test_hierarchy() {
        let mut kb = EngineKnowledge::new();
        let json = r#"{
            "engine_version": "5.4",
            "classes": [
                {"name": "UObject", "parent": "", "header": "UObject/Object.h", "module": "CoreUObject"},
                {"name": "AActor", "parent": "UObject", "header": "GameFramework/Actor.h", "module": "Engine"},
                {"name": "APawn", "parent": "AActor", "header": "GameFramework/Pawn.h", "module": "Engine"},
                {"name": "ACharacter", "parent": "APawn", "header": "GameFramework/Character.h", "module": "Engine"},
                {"name": "UActorComponent", "parent": "UObject", "header": "Components/ActorComponent.h", "module": "Engine"},
                {"name": "USceneComponent", "parent": "UActorComponent", "header": "Components/SceneComponent.h", "module": "Engine"},
                {"name": "UStaticMeshComponent", "parent": "USceneComponent", "header": "Components/StaticMeshComponent.h", "module": "Engine"}
            ],
            "structs": [],
            "enums": []
        }"#;
        kb.load_metadata(json).unwrap();

        assert!(kb.is_child_of("ACharacter", "AActor"));
        assert!(kb.is_child_of("ACharacter", "UObject"));
        assert!(kb.is_child_of("APawn", "AActor"));
        assert!(!kb.is_child_of("AActor", "ACharacter"));
        assert!(kb.is_engine_actor("ACharacter"));
        assert!(kb.is_engine_actor("APawn"));
        assert!(kb.is_engine_component("UStaticMeshComponent"));
        assert!(kb.is_engine_component("USceneComponent"));
        assert!(!kb.is_engine_component("AActor"));
    }

    #[test]
    fn test_named_colors() {
        let kb = EngineKnowledge::new();
        // Basic colors
        assert!(kb.is_named_color("red"));
        assert!(kb.is_named_color("Red"));
        assert!(kb.is_named_color("RED"));
        assert!(!kb.is_named_color("nonexistent_color"));

        // Resolve to FLinearColor constructor
        let sunset = kb.resolve_named_color("sunset").unwrap();
        assert!(sunset.starts_with("FLinearColor("));
        assert!(sunset.contains("0.7"));
        assert!(sunset.contains("0.3"));

        // Temperature colors from JsonValueHelper
        assert!(kb.is_named_color("warm"));
        assert!(kb.is_named_color("candlelight"));
        assert!(kb.is_named_color("daylight"));

        // Game colors
        assert!(kb.is_named_color("health"));
        assert!(kb.is_named_color("mana"));

        // Rarity colors
        assert!(kb.is_named_color("legendary"));
        assert!(kb.is_named_color("epic"));

        // Raw RGBA access
        let rgba = kb.get_named_color_rgba("white").unwrap();
        assert_eq!(rgba, [1.0, 1.0, 1.0, 1.0]);
        let transparent = kb.get_named_color_rgba("transparent").unwrap();
        assert_eq!(transparent, [0.0, 0.0, 0.0, 0.0]);
    }

    #[test]
    fn test_constructor_resolution() {
        let kb = EngineKnowledge::new();

        // FVector(x, y, z)
        let v = kb
            .resolve_constructor("FVector", &["1.0".into(), "2.0".into(), "3.0".into()])
            .unwrap();
        assert_eq!(v, "FVector(1.0, 2.0, 3.0)");

        // FVector zero
        let vz = kb.resolve_constructor("FVector", &[]).unwrap();
        assert_eq!(vz, "FVector::ZeroVector");

        // FVector uniform
        let vu = kb.resolve_constructor("FVector", &["5.0".into()]).unwrap();
        assert_eq!(vu, "FVector(5.0)");

        // FRotator
        let r = kb
            .resolve_constructor("FRotator", &["0.0".into(), "90.0".into(), "0.0".into()])
            .unwrap();
        assert_eq!(r, "FRotator(0.0, 90.0, 0.0)");

        // FLinearColor(r, g, b)
        let c3 = kb
            .resolve_constructor("FLinearColor", &["1.0".into(), "0.5".into(), "0.0".into()])
            .unwrap();
        assert_eq!(c3, "FLinearColor(1.0f, 0.5f, 0.0f, 1.0f)");

        // FLinearColor(r, g, b, a)
        let c4 = kb
            .resolve_constructor(
                "FLinearColor",
                &["1.0".into(), "0.5".into(), "0.0".into(), "0.8".into()],
            )
            .unwrap();
        assert_eq!(c4, "FLinearColor(1.0f, 0.5f, 0.0f, 0.8f)");

        // FMargin uniform
        let m1 = kb.resolve_constructor("FMargin", &["5.0".into()]).unwrap();
        assert_eq!(m1, "FMargin(5.0f)");

        // FMargin horizontal/vertical
        let m2 = kb
            .resolve_constructor("FMargin", &["10.0".into(), "5.0".into()])
            .unwrap();
        assert_eq!(m2, "FMargin(10.0f, 5.0f)");

        // FMargin full
        let m4 = kb
            .resolve_constructor(
                "FMargin",
                &["1.0".into(), "2.0".into(), "3.0".into(), "4.0".into()],
            )
            .unwrap();
        assert_eq!(m4, "FMargin(1.0f, 2.0f, 3.0f, 4.0f)");

        // Unknown type returns None
        assert!(kb
            .resolve_constructor("FUnknownType", &["1".into()])
            .is_none());

        // Wrong arg count returns None
        assert!(kb
            .resolve_constructor("FVector", &["1".into(), "2".into()])
            .is_none());
    }

    #[test]
    fn test_property_string_format() {
        let kb = EngineKnowledge::new();

        // FVector property string
        let vs = kb
            .format_property_string("FVector", &["1.0".into(), "2.0".into(), "3.0".into()])
            .unwrap();
        assert_eq!(vs, "(X=1.0,Y=2.0,Z=3.0)");

        // FRotator property string
        let rs = kb
            .format_property_string("FRotator", &["0.0".into(), "90.0".into(), "0.0".into()])
            .unwrap();
        assert_eq!(rs, "(Pitch=0.0,Yaw=90.0,Roll=0.0)");

        // FLinearColor property string
        let cs = kb
            .format_property_string(
                "FLinearColor",
                &["1.0".into(), "0.5".into(), "0.0".into(), "1.0".into()],
            )
            .unwrap();
        assert_eq!(cs, "(R=1.0,G=0.5,B=0.0,A=1.0)");

        // Unknown type returns None
        assert!(kb
            .format_property_string("FUnknownType", &["1".into()])
            .is_none());
    }

    #[test]
    fn test_module_resolution() {
        let mut kb = EngineKnowledge::new();
        let json = r#"{
            "engine_version": "5.4",
            "classes": [
                {"name": "UNiagaraComponent", "parent": "USceneComponent", "header": "NiagaraComponent.h", "module": "Niagara"}
            ],
            "structs": [],
            "enums": []
        }"#;
        kb.load_metadata(json).unwrap();
        assert_eq!(kb.get_module_for_type("UNiagaraComponent"), Some("Niagara"));
        assert_eq!(kb.get_module_for_type("NiagaraComponent"), Some("Niagara"));
    }
}
